package ru.neverland.townypopulation;

import java.math.*;
import java.util.*;
import ru.neverland.townypopulation.model.DistrictCohorts;
import static ru.neverland.townypopulation.model.DistrictCohorts.*;

public final class DistrictCohortsSmoke {
    static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}interface Work{void run()throws Exception;}static void denied(Work work,String why)throws Exception{try{work.run();}catch(Exception expected){check(true,why);return;}throw new AssertionError(why);}
    static BigDecimal d(String text){return new BigDecimal(text);}static District district(String id){return new District(id,"Район "+id,"RESIDENTIAL",2,2,true,List.of(new Service("water","Вода",0,2,false)));}
    static Input input(int n,int workers,int employed,int housing,int jobs,Map<String,Source> sources,Map<String,District> districts,Map<String,String> assignments){return new Input(n,workers,employed,housing,jobs,d("123.4567890123456789"),d("321.0987654321098765"),d("1.1234567890123456789"),d("0.75"),sources,districts,assignments);}
    static Group group(Result result,String id){return result.groups().stream().filter(g->g.id().equals(id)).findFirst().orElseThrow();}
    public static void main(String[] args)throws Exception{
        var districts=Map.of("homes",district("homes"),"works",new District("works","Промышленность","INDUSTRIAL",1,0,true,List.of()));var sources=Map.of("@base",new Source("@base",20,12),"residential_quarter",new Source("residential_quarter",100,0),"forge",new Source("forge",0,100));var assignment=Map.of("residential_quarter","homes","forge","works");var input=input(120,72,70,120,112,sources,districts,assignment);var result=DistrictCohorts.calculate(input);var homes=group(result,"district:homes");var city=group(result,CITY);var works=group(result,"district:works");
        check(homes.population()==100&&city.population()==20&&works.population()==0,"resident totals follow housing while base settlement remains explicitly unassigned");check(homes.housing()==100&&works.jobs()==100&&homes.jobs()==0,"residence and actual location of jobs are separate dimensions");check(homes.employed()>homes.jobs()&&result.employed()==70,"citywide employment estimate does not pretend residents work in their home district");check(result.groups().stream().allMatch(g->g.employed()+g.unemployed()+g.other()==g.population()),"three virtual cohorts partition each group exactly");
        check(result.foodDemand().compareTo(input.foodPerResident().multiply(BigDecimal.valueOf(120)))==0&&result.waterDemand().compareTo(d("90"))==0,"food and water needs equal original city demand exactly");check(result.groups().stream().map(Group::foodSupply).reduce(BigDecimal.ZERO,BigDecimal::add).compareTo(input.foodSupply())==0,"high precision city food potential is never duplicated by groups");check(!homes.district().services().get(0).known(),"unknown neighborhood service remains unknown rather than insufficient");
        var noDistricts=DistrictCohorts.calculate(input(123,74,12,20,12,sources,Map.of(),Map.of()));check(noDistricts.groups().size()==1&&noDistricts.groups().get(0).population()==123&&noDistricts.housing()==20,"legacy city without districts retains every resident including overcrowding");
        var noHousing=DistrictCohorts.calculate(input(100,60,12,0,12,Map.of(),districts,Map.of()));check(group(noHousing,CITY).population()==100&&noHousing.groups().stream().mapToInt(Group::population).sum()==100,"missing housing never deletes people or assigns them to arbitrary district");
        var extra=DistrictCohorts.calculate(input(120,72,70,240,112,sources,districts,assignment));check(group(extra,"district:homes").housing()==100&&group(extra,CITY).housing()==140,"unexplained city housing is kept unassigned instead of fabricating building capacity");
        var capped=DistrictCohorts.calculate(input(1_000_000,600_000,600_000,10_000_000,10_000_000,Map.of("a",new Source("a",10_000_000,10_000_000),"b",new Source("b",10_000_000,10_000_000)),Map.of("a",district("a"),"b",district("b")),Map.of("a","a","b","b")));check(group(capped,"district:a").housing()==5_000_000&&group(capped,"district:b").housing()==5_000_000&&capped.population()==1_000_000,"global capacity cap is apportioned without multiplying local places");
        var tie=DistrictCohorts.calculate(input(1,1,0,2,0,Map.of("a",new Source("a",1,0),"b",new Source("b",1,0)),Map.of("a",district("a"),"b",district("b")),Map.of("a","a","b","b")));check(group(tie,"district:a").population()==1&&group(tie,"district:b").population()==0,"largest remainder uses stable key tie instead of random restart reassignment");
        var empty=DistrictCohorts.calculate(input(0,0,0,120,112,sources,districts,assignment));check(empty.groups().stream().allMatch(g->g.population()==0&&g.foodDemand().signum()==0)&&group(empty,CITY).foodSupply().compareTo(empty.foodSupply())==0,"zero residents preserve city supply potential without generating people or demand");
        var veryPrecise=new Input(120,72,70,120,112,d("999999999.99999999999999999999"),d("0.00000000000000000001"),d("1000"),d("0.001"),sources,districts,assignment);check(DistrictCohorts.calculate(veryPrecise).foodSupply().compareTo(veryPrecise.foodSupply())==0,"allocation supports amount-weight products beyond long and tiny decimal water supplies");
        denied(()->input(10,11,0,20,12,sources,districts,assignment),"workforce cannot exceed population");denied(()->input(10,6,7,20,12,sources,districts,assignment),"employed cannot exceed workforce");denied(()->input(10,6,6,20,5,sources,districts,assignment),"city cannot employ more than available jobs");denied(()->input(10,6,6,20,12,sources,districts,Map.of("forge","unknown")),"unknown assigned district fails instead of hiding an inconsistent source");denied(()->input(10,6,6,20,12,sources,districts,Map.of("@base","homes")),"base settlement cannot be silently assigned to a district");denied(()->result.groups().clear(),"group snapshot immutable");denied(()->homes.district().services().clear(),"neighborhood needs immutable");
        var random=new Random(52);for(int i=0;i<10000;i++){int pop=random.nextInt(1_000_001),work=random.nextInt(pop+1),jobs=random.nextInt(10_000_001),employed=random.nextInt(Math.min(work,jobs)+1),housing=random.nextInt(10_000_001);var shuffled=new LinkedHashMap<String,Source>();if(random.nextBoolean()){shuffled.putAll(sources);}else{sources.entrySet().stream().sorted(Map.Entry.<String,Source>comparingByKey().reversed()).forEach(e->shuffled.put(e.getKey(),e.getValue()));}var snapshot=DistrictCohorts.calculate(input(pop,work,employed,housing,jobs,shuffled,districts,assignment));if(snapshot.groups().stream().anyMatch(g->g.workforce()>g.population()||g.employed()>g.workforce()))throw new AssertionError("invalid subgroup");}
        check(true,"10000 distributions retain population, capacities, employment and exact decimal supply/demand totals");
        System.out.println("DistrictCohortsSmoke PASS "+checks+" checks and 10000 conserved allocations");
    }
}
